"""
NexLev MCP Bridge — Stdio proxy to NexLev's remote MCP endpoint.
Same pattern as the vidIQ bridge. Reads API key from mcp_config.json.
Auto-discovers all 74 NexLev tools from the remote server.
"""
import os
import sys
import json
import asyncio
import aiohttp
from pathlib import Path
from mcp.server.stdio import stdio_server
from mcp.server import Server
from mcp.types import Tool, TextContent

# --- Configuration ---
NEXLEV_MCP_URL = "https://prod.dashboard.nexlev.io/api/claude-mcp"

CONFIG_PATHS = [
    Path(os.path.expanduser("~")) / ".gemini" / "config" / "mcp_config.json",
]

local_server = Server("nexlev-mcp-bridge")

# --- Session State ---
_remote_tools = None
_http_session = None
_request_counter = 0
_current_api_key = None
_initialized = False


def _next_id():
    global _request_counter
    _request_counter += 1
    return _request_counter


def _read_api_key():
    """Read the NexLev API key from config file or env var."""
    for config_path in CONFIG_PATHS:
        try:
            if config_path.exists():
                with open(config_path, "r") as f:
                    config = json.load(f)
                servers = config.get("mcpServers", {})
                nexlev = servers.get("nexlev", {})
                env = nexlev.get("env", {})
                key = env.get("NEXLEV_API_KEY", "")
                if key:
                    return key
        except Exception:
            continue
    return os.environ.get("NEXLEV_API_KEY", "")


def _get_headers():
    """Build headers with API key as Bearer token."""
    api_key = _read_api_key()
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json, text/event-stream",
    }
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"
    return headers


def _parse_sse_sync(text):
    """Parse SSE response text and return the JSON-RPC result."""
    for line in text.split("\n"):
        line = line.strip()
        if line.startswith("data:"):
            data_str = line[5:].strip()
            if data_str:
                try:
                    return json.loads(data_str)
                except json.JSONDecodeError:
                    continue
    return None


async def _parse_response(response):
    """Parse response — handles both JSON and SSE formats."""
    content_type = response.headers.get("Content-Type", "")
    if "text/event-stream" in content_type:
        text = await response.text()
        return _parse_sse_sync(text)
    else:
        return await response.json()


def _invalidate():
    """Reset all state."""
    global _remote_tools, _current_api_key, _initialized
    _remote_tools = None
    _current_api_key = None
    _initialized = False


async def _get_session():
    """Get or create HTTP session."""
    global _http_session
    if _http_session is None or _http_session.closed:
        _http_session = aiohttp.ClientSession()
    return _http_session


async def _init_and_discover():
    """Initialize connection and discover tools."""
    global _remote_tools, _current_api_key, _initialized

    current_key = _read_api_key()
    if not current_key:
        raise Exception(
            "No API key. Set NEXLEV_API_KEY in ~/.gemini/config/mcp_config.json under nexlev.env"
        )

    if _initialized and current_key == _current_api_key:
        return

    _invalidate()
    _current_api_key = current_key
    session = await _get_session()
    headers = _get_headers()

    # Step 1: Initialize
    init_req = {
        "jsonrpc": "2.0",
        "id": _next_id(),
        "method": "initialize",
        "params": {
            "protocolVersion": "2025-03-26",
            "capabilities": {},
            "clientInfo": {"name": "nexlev-mcp-bridge", "version": "1.0.0"}
        }
    }

    try:
        async with session.post(
            NEXLEV_MCP_URL, headers=headers, json=init_req,
            timeout=aiohttp.ClientTimeout(total=30)
        ) as resp:
            if resp.status == 401:
                _invalidate()
                raise Exception("API key rejected (401). Update NEXLEV_API_KEY in mcp_config.json")
            if resp.status != 200:
                _invalidate()
                text = await resp.text()
                raise Exception(f"Init failed: HTTP {resp.status} - {text}")
            await _parse_response(resp)
    except (aiohttp.ClientError, asyncio.TimeoutError) as e:
        _invalidate()
        raise Exception(f"Connection failed: {e}")

    # Step 2: Initialized notification
    try:
        async with session.post(
            NEXLEV_MCP_URL, headers=headers,
            json={"jsonrpc": "2.0", "method": "notifications/initialized", "params": {}},
            timeout=aiohttp.ClientTimeout(total=10)
        ) as resp:
            pass
    except Exception:
        pass

    # Step 3: Discover tools
    try:
        async with session.post(
            NEXLEV_MCP_URL, headers=headers,
            json={"jsonrpc": "2.0", "id": _next_id(), "method": "tools/list", "params": {}},
            timeout=aiohttp.ClientTimeout(total=30)
        ) as resp:
            if resp.status == 200:
                result = await _parse_response(resp)
                if result and "result" in result:
                    tools_data = result["result"]
                    if isinstance(tools_data, dict) and "tools" in tools_data:
                        _remote_tools = tools_data["tools"]
    except Exception:
        pass

    _initialized = True


# --- Fallback hardcoded tool list (core NexLev tools) ---
NEXLEV_TOOLS = [
    Tool(name="find_long_form_channels", description="Find long-form YouTube channels by niche, size, and growth rate", inputSchema={"type": "object", "properties": {"query": {"type": "string", "description": "Search query or niche"}}, "required": ["query"]}),
    Tool(name="find_shorts_channels", description="Find Shorts-only channels by niche, engagement, and upload frequency", inputSchema={"type": "object", "properties": {"query": {"type": "string", "description": "Search query or niche"}}, "required": ["query"]}),
    Tool(name="get_similar_channels", description="Discover channels with overlapping audience and content style", inputSchema={"type": "object", "properties": {"channel_id": {"type": "string", "description": "YouTube channel ID or URL"}}, "required": ["channel_id"]}),
    Tool(name="channel_resolver", description="Resolve any channel ID, handle, custom URL, or alias to a canonical ID", inputSchema={"type": "object", "properties": {"query": {"type": "string", "description": "Channel handle, URL, or ID"}}, "required": ["query"]}),
    Tool(name="get_channel_analytics", description="Full channel snapshot — subscribers, views, revenue, and upload pace", inputSchema={"type": "object", "properties": {"channel_id": {"type": "string", "description": "YouTube channel ID or URL"}}, "required": ["channel_id"]}),
    Tool(name="get_daily_analytics", description="Daily performance trends and growth tracking for any channel", inputSchema={"type": "object", "properties": {"channel_id": {"type": "string", "description": "YouTube channel ID or URL"}}, "required": ["channel_id"]}),
    Tool(name="get_geography_revenue", description="Revenue estimates, RPM by country, and geographic demographics", inputSchema={"type": "object", "properties": {"channel_id": {"type": "string", "description": "YouTube channel ID or URL"}}, "required": ["channel_id"]}),
    Tool(name="batch_channel_metrics", description="Compare up to 10 channels side-by-side in a single request", inputSchema={"type": "object", "properties": {"channel_ids": {"type": "string", "description": "Comma-separated channel IDs"}}, "required": ["channel_ids"]}),
    Tool(name="search_youtube_suggested_videos", description="Search YouTube suggested videos with outlier scores and engagement filters", inputSchema={"type": "object", "properties": {"query": {"type": "string", "description": "Search query"}}, "required": ["query"]}),
    Tool(name="search_viral_videos_small_channels", description="Find breakout hits from low-subscriber channels", inputSchema={"type": "object", "properties": {"query": {"type": "string", "description": "Search query or niche"}}, "required": ["query"]}),
    Tool(name="get_similar_videos", description="Find videos similar to any input by content match and engagement", inputSchema={"type": "object", "properties": {"video_id": {"type": "string", "description": "YouTube video ID or URL"}}, "required": ["video_id"]}),
    Tool(name="youtube_search", description="General YouTube search across videos, channels, and playlists", inputSchema={"type": "object", "properties": {"query": {"type": "string", "description": "Search query"}}, "required": ["query"]}),
    Tool(name="youtube_video_details", description="Fetch full metadata and statistics for any YouTube video", inputSchema={"type": "object", "properties": {"video_id": {"type": "string", "description": "YouTube video ID or URL"}}, "required": ["video_id"]}),
    Tool(name="youtube_video_comments", description="Retrieve top comments from any YouTube video", inputSchema={"type": "object", "properties": {"video_id": {"type": "string", "description": "YouTube video ID or URL"}}, "required": ["video_id"]}),
    Tool(name="get_video_transcript", description="Get the full transcript of any YouTube video", inputSchema={"type": "object", "properties": {"video_id": {"type": "string", "description": "YouTube video ID or URL"}}, "required": ["video_id"]}),
    Tool(name="get_niche_overview", description="Audience profile, content formats, and brand fit for any niche", inputSchema={"type": "object", "properties": {"niche": {"type": "string", "description": "Niche name"}}, "required": ["niche"]}),
    Tool(name="check_channel_monetization", description="Check monetization eligibility and brand deal signals", inputSchema={"type": "object", "properties": {"channel_id": {"type": "string", "description": "YouTube channel ID or URL"}}, "required": ["channel_id"]}),
    Tool(name="get_video_rpm", description="Get estimated RPM and revenue data for any YouTube video", inputSchema={"type": "object", "properties": {"video_id": {"type": "string", "description": "YouTube video ID or URL"}}, "required": ["video_id"]}),
    Tool(name="similar_thumbnails", description="Search and compare thumbnails across millions of YouTube videos", inputSchema={"type": "object", "properties": {"query": {"type": "string", "description": "Search query or video URL"}}, "required": ["query"]}),
    Tool(name="latest_discovered_faceless_niches", description="Find top-performing faceless or AI-generated channels in any niche", inputSchema={"type": "object", "properties": {}, "required": []}),
    Tool(name="check_faceless_channel", description="Verify whether a specific channel uses faceless or AI-driven content", inputSchema={"type": "object", "properties": {"channel_id": {"type": "string", "description": "YouTube channel ID or URL"}}, "required": ["channel_id"]}),
]


@local_server.list_tools()
async def handle_list_tools() -> list[Tool]:
    try:
        await _init_and_discover()
    except Exception:
        pass
    if _remote_tools:
        return [
            Tool(
                name=t.get("name", "unknown"),
                description=t.get("description", ""),
                inputSchema=t.get("inputSchema", {"type": "object", "properties": {}, "required": []})
            )
            for t in _remote_tools
        ]
    return NEXLEV_TOOLS


@local_server.call_tool()
async def handle_call_tool(name: str, arguments: dict) -> list[TextContent]:
    for attempt in range(2):
        try:
            await _init_and_discover()
        except Exception as e:
            return [TextContent(type="text", text=f"Error: {e}")]

        session = await _get_session()
        headers = _get_headers()

        call_request = {
            "jsonrpc": "2.0",
            "id": _next_id(),
            "method": "tools/call",
            "params": {"name": name, "arguments": arguments}
        }

        try:
            async with session.post(
                NEXLEV_MCP_URL, headers=headers, json=call_request,
                timeout=aiohttp.ClientTimeout(total=60)
            ) as response:
                if response.status == 401:
                    _invalidate()
                    if attempt == 0:
                        continue
                    return [TextContent(
                        type="text",
                        text="Error: API key rejected (401). Update NEXLEV_API_KEY in mcp_config.json"
                    )]

                if response.status != 200:
                    text = await response.text()
                    if attempt == 0:
                        _invalidate()
                        continue
                    return [TextContent(type="text", text=f"Error: HTTP {response.status} - {text}")]

                result = await _parse_response(response)

                if result is None:
                    return [TextContent(type="text", text="Error: Empty response from NexLev")]

                if "error" in result:
                    error = result["error"]
                    return [TextContent(type="text", text=f"NexLev error: {error.get('message', str(error))}")]

                if "result" in result:
                    content = result["result"]
                    if isinstance(content, dict) and "content" in content:
                        texts = []
                        for item in content["content"]:
                            if isinstance(item, dict) and item.get("type") == "text":
                                texts.append(item.get("text", ""))
                            else:
                                texts.append(json.dumps(item, indent=2))
                        return [TextContent(type="text", text="\n".join(texts))]
                    else:
                        return [TextContent(type="text", text=json.dumps(content, indent=2))]

                return [TextContent(type="text", text=json.dumps(result, indent=2))]

        except asyncio.TimeoutError:
            return [TextContent(type="text", text="Error: Request timed out (60s). Try again.")]
        except aiohttp.ClientError as e:
            _invalidate()
            if attempt == 0:
                continue
            return [TextContent(type="text", text=f"Error: Connection failed - {e}")]
        except Exception as e:
            return [TextContent(type="text", text=f"Error: {type(e).__name__} - {e}")]

    return [TextContent(type="text", text="Error: Failed after 2 attempts.")]


async def main():
    async with stdio_server() as (read_stream, write_stream):
        await local_server.run(read_stream, write_stream, local_server.create_initialization_options())


if __name__ == "__main__":
    asyncio.run(main())

